/**
 * Upload Module
 * Pre-signed URL upload (most secure and efficient)
 */

import { getPresignedUrlEndpoint, uploadDefaults } from "../const";
import type {
  PresignedUrlRequest,
  PresignedUrlResponse,
  PresignedUploadOptions,
  UploadResult
} from "./types";

// ============================================================================
// Internal Helper Functions
// ============================================================================

/**
 * Get file extension from filename
 */
function getFileExtension(fileName: string): string {
  const lastDotIndex = fileName.lastIndexOf('.');
  if (lastDotIndex === -1 || lastDotIndex === fileName.length - 1) {
    return '';
  }
  return fileName.substring(lastDotIndex).toLowerCase();
}

/**
 * Validate file extension against allowed extensions
 */
function validateFileExtension(fileName: string, allowedExtensions?: string[]): boolean {
  // If no restrictions, allow all
  if (!allowedExtensions || allowedExtensions.length === 0) {
    return true;
  }

  const fileExt = getFileExtension(fileName);
  if (!fileExt) {
    return false; // No extension and restrictions exist
  }

  // Normalize allowed extensions (ensure they start with '.')
  const normalizedAllowed = allowedExtensions.map(ext =>
    ext.startsWith('.') ? ext.toLowerCase() : `.${ext.toLowerCase()}`
  );

  return normalizedAllowed.includes(fileExt);
}

// ============================================================================
// Internal API Communication
// ============================================================================

/**
 * Get pre-signed upload URL from backend
 * @param request - Pre-signed URL request parameters
 * @returns Promise resolving to PresignedUrlResponse
 * @throws Error if request fails or returns invalid data
 */
async function getPresignedUrl(
  request: PresignedUrlRequest
): Promise<PresignedUrlResponse> {
  try {
    const response = await fetch(getPresignedUrlEndpoint(), {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify(request),
    });

    if (!response.ok) {
      throw new Error(
        `Failed to get pre-signed URL: ${response.status} ${response.statusText}`
      );
    }

    const result = await response.json();

    // Backend returns DataResult<PresignedUrlResponse>
    if (!result.success) {
      throw new Error(result.errorMessage || "Failed to get pre-signed URL");
    }

    const data = result.data;

    // Validate required fields
    if (!data.uploadUrl || !data.fileUrl || !data.objectKey) {
      throw new Error("Invalid pre-signed URL response: missing required fields");
    }

    return {
      uploadUrl: data.uploadUrl,
      fileUrl: data.fileUrl,
      objectKey: data.objectKey,
      expiration: data.expiration,
      method: data.method || "PUT",
    };
  } catch (error) {
    throw new Error(
      `Failed to fetch pre-signed URL: ${
        error instanceof Error ? error.message : "Unknown error"
      }`
    );
  }
}

// ============================================================================
// Public Upload Function
// ============================================================================

/**
 * Upload file directly to OSS using pre-signed URL (recommended)
 *
 * This is the most secure and efficient way to upload files.
 * Backend generates a pre-signed URL, and client uploads directly to OSS.
 *
 * @param file - The File object to upload
 * @param options - Pre-signed upload options
 * @returns Promise resolving to upload result
 *
 * @example
 * ```typescript
 * const result = await uploadWithPresignedUrl(file, {
 *   pathPrefix: 'zoer/user-upload',
 *   fileName: 'my-image.jpg',
 *   onProgress: (progress) => console.log(`${progress}%`),
 *   maxSize: 10 * 1024 * 1024 // 10MB
 * })
 *
 * if (result.success) {
 *   console.log('File uploaded:', result.fileKey)
 *   console.log('File URL:', result.url)
 * }
 * ```
 */
export async function uploadWithPresignedUrl(
  file: File,
  options: PresignedUploadOptions = {}
): Promise<UploadResult> {
  // Use default configuration from uploadDefaults
  const maxSize = uploadDefaults.maxSize;
  const pathPrefix = uploadDefaults.pathPrefix;
  const allowedExtensions = options.allowedExtensions ?? uploadDefaults.allowedExtensions;
  const fileName = options.fileName || file.name;

  // Validate file extension
  if (!validateFileExtension(fileName, allowedExtensions)) {
    const allowedList = allowedExtensions && allowedExtensions.length > 0
      ? allowedExtensions.join(', ')
      : 'any';
    return {
      success: false,
      error: `File extension not allowed. Allowed extensions: ${allowedList}`,
      timestamp: Date.now(),
    };
  }

  // Validate file size
  if (file.size > maxSize) {
    return {
      success: false,
      error: `File size ${file.size} bytes exceeds maximum ${maxSize} bytes`,
      timestamp: Date.now(),
    };
  }

  try {
    // 1. Get pre-signed URL from backend
    const presignedData = await getPresignedUrl({
      fileName,
      contentType: file.type,
      pathPrefix,
    });

    // 2. Upload file to OSS using pre-signed URL
    const uploadResult = await uploadToPresignedUrl(file, presignedData, {
      headers: options.headers,
      onProgress: options.onProgress,
    });

    if (!uploadResult.success) {
      return uploadResult;
    }

    return {
      success: true,
      fileKey: presignedData.objectKey,
      url: presignedData.fileUrl,
      timestamp: Date.now(),
    };
  } catch (error) {
    return {
      success: false,
      error: error instanceof Error ? error.message : "Pre-signed upload failed",
      timestamp: Date.now(),
    };
  }
}

/**
 * Internal function to upload file to pre-signed URL with progress tracking
 */
function uploadToPresignedUrl(
  file: File,
  presignedData: PresignedUrlResponse,
  options?: {
    headers?: Record<string, string>;
    onProgress?: (progress: number) => void;
  }
): Promise<UploadResult> {
  return new Promise((resolve) => {
    const xhr = new XMLHttpRequest();

    // Track upload progress
    if (options?.onProgress) {
      xhr.upload.addEventListener("progress", (event) => {
        if (event.lengthComputable) {
          const progress = Math.round((event.loaded / event.total) * 100);
          options.onProgress?.(progress);
        }
      });
    }

    // Handle completion
    xhr.addEventListener("load", () => {
      if (xhr.status >= 200 && xhr.status < 300) {
        resolve({
          success: true,
          timestamp: Date.now(),
        });
      } else {
        resolve({
          success: false,
          error: `OSS upload failed with status ${xhr.status}`,
          timestamp: Date.now(),
        });
      }
    });

    // Handle errors
    xhr.addEventListener("error", () => {
      resolve({
        success: false,
        error: "Network error during OSS upload",
        timestamp: Date.now(),
      });
    });

    xhr.addEventListener("abort", () => {
      resolve({
        success: false,
        error: "OSS upload aborted",
        timestamp: Date.now(),
      });
    });

    // Send request using the method from backend (usually PUT)
    xhr.open(presignedData.method, presignedData.uploadUrl);

    // Set headers
    if (options?.headers) {
      Object.entries(options.headers).forEach(([key, value]) => {
        xhr.setRequestHeader(key, value);
      });
    }

    // Set content type
    xhr.setRequestHeader("Content-Type", file.type || "application/octet-stream");

    xhr.send(file);
  });
}
