/**
 * Get base URL from environment variable or use default
 * Supports Next.js NEXT_PUBLIC_BASE_URL
 */
function getBaseUrl(): string {
  if (typeof process !== "undefined" && process.env) {
    return (
      process.env.NEXT_PUBLIC_BASE_URL || process.env.NEXT_PUBLIC_APP_URL || "/"
    );
  }
  return "/";
}

export const prefix = "zoer_proxy/zapi/integration";

/**
 * Get the presigned URL endpoint
 * Automatically reads from NEXT_PUBLIC_BASE_URL environment variable
 * @returns Full endpoint URL
 */
export function getPresignedUrlEndpoint(): string {
  const base = getBaseUrl().endsWith("/")
    ? getBaseUrl().slice(0, -1)
    : getBaseUrl();
  return `${base}/${prefix}/presigned-url`;
}

/**
 * Get the text-to-image endpoint
 * Automatically reads from NEXT_PUBLIC_BASE_URL environment variable
 * @returns Full endpoint URL
 */
export function getTextToImageEndpoint(): string {
  const base = getBaseUrl().endsWith("/")
    ? getBaseUrl().slice(0, -1)
    : getBaseUrl();
  return `${base}/${prefix}/text-to-image`;
}

// Stripe endpoints removed - Stripe now uses direct SDK integration
// No backend proxy needed

// Upload default configuration
export const uploadDefaults = {
  /** Default path prefix for uploaded files */
  pathPrefix: "zoer/user-upload",
  /** Default maximum file size (5MB) */
  maxSize: 5 * 1024 * 1024,
  /** Allowed file extensions (empty array means all types allowed) */
  allowedExtensions: [] as string[],
} as const;
