/**
 * Stripe Module
 * Direct implementation using Stripe Node.js SDK
 * No Zoer backend involved - completely independent integration
 */

import Stripe from 'stripe'
import type {
  CreatePaymentIntentOptions,
  PaymentIntentResult,
  ConfirmPaymentIntentRequest,
  CancelPaymentIntentRequest,
  CreateCheckoutSessionOptions,
  CheckoutSessionResult,
  GetCheckoutSessionRequest,
  CustomerResult,
  CreateCustomerOptions,
  UpdateCustomerRequest,
  ConstructWebhookEventOptions,
  WebhookVerificationResult,
  StripeResult,
  GetCheckoutSessionResponse,
} from "./types";

// ============================================================================
// Payment Intent Functions
// ============================================================================

/**
 * Create a Payment Intent
 *
 * Directly calls Stripe API using user's secret key.
 * No Zoer backend involved.
 *
 * @param options - Payment intent options with user's Stripe secret key
 * @returns Promise resolving to payment intent result
 *
 * @example
 * ```typescript
 * // In Next.js API Route
 * import { stripe } from '@zoerai/integration'
 *
 * const result = await stripe.createPaymentIntent({
 *   stripeSecretKey: process.env.STRIPE_SECRET_KEY!,
 *   request: {
 *     amount: 2000, // $20.00 in cents
 *     currency: 'usd',
 *     automaticPaymentMethods: { enabled: true },
 *   }
 * })
 *
 * if (result.success) {
 *   return { clientSecret: result.data.clientSecret }
 * }
 * ```
 */
export async function createPaymentIntent(
  options: CreatePaymentIntentOptions
): Promise<PaymentIntentResult> {
  try {
    const stripe = new Stripe(options.stripeSecretKey)

    const paymentIntent = await stripe.paymentIntents.create({
      amount: options.request.amount,
      currency: options.request.currency,
      automatic_payment_methods: options.request.automaticPaymentMethods,
      customer: options.request.customerId,
      description: options.request.description,
      metadata: options.request.metadata
    })

    return {
      success: true,
      data: {
        id: paymentIntent.id,
        clientSecret: paymentIntent.client_secret!,
        status: paymentIntent.status,
        amount: paymentIntent.amount,
        currency: paymentIntent.currency
      },
      timestamp: Date.now()
    }
  } catch (error) {
    return {
      success: false,
      error: error instanceof Error ? error.message : 'Payment intent creation failed',
      timestamp: Date.now()
    }
  }
}

/**
 * Confirm a Payment Intent
 *
 * Used to confirm a payment intent with a payment method.
 *
 * @param stripeSecretKey - User's Stripe secret key
 * @param request - Confirm payment intent request
 * @returns Promise resolving to payment intent result
 *
 * @example
 * ```typescript
 * const result = await stripe.confirmPaymentIntent(
 *   process.env.STRIPE_SECRET_KEY!,
 *   {
 *     paymentIntentId: 'pi_xxx',
 *     paymentMethodId: 'pm_xxx'
 *   }
 * )
 * ```
 */
export async function confirmPaymentIntent(
  stripeSecretKey: string,
  request: ConfirmPaymentIntentRequest
): Promise<PaymentIntentResult> {
  try {
    const stripe = new Stripe(stripeSecretKey)

    const paymentIntent = await stripe.paymentIntents.confirm(
      request.paymentIntentId,
      {
        payment_method: request.paymentMethodId
      }
    )

    return {
      success: true,
      data: {
        id: paymentIntent.id,
        clientSecret: paymentIntent.client_secret!,
        status: paymentIntent.status,
        amount: paymentIntent.amount,
        currency: paymentIntent.currency
      },
      timestamp: Date.now()
    }
  } catch (error) {
    return {
      success: false,
      error: error instanceof Error ? error.message : 'Payment intent confirmation failed',
      timestamp: Date.now()
    }
  }
}

/**
 * Cancel a Payment Intent
 *
 * Cancels a payment intent that hasn't been confirmed yet.
 *
 * @param stripeSecretKey - User's Stripe secret key
 * @param request - Cancel payment intent request
 * @returns Promise resolving to payment intent result
 *
 * @example
 * ```typescript
 * const result = await stripe.cancelPaymentIntent(
 *   process.env.STRIPE_SECRET_KEY!,
 *   {
 *     paymentIntentId: 'pi_xxx',
 *     cancellationReason: 'requested_by_customer'
 *   }
 * )
 * ```
 */
export async function cancelPaymentIntent(
  stripeSecretKey: string,
  request: CancelPaymentIntentRequest
): Promise<PaymentIntentResult> {
  try {
    const stripe = new Stripe(stripeSecretKey)

    const paymentIntent = await stripe.paymentIntents.cancel(
      request.paymentIntentId,
      {
        cancellation_reason: request.cancellationReason as any
      }
    )

    return {
      success: true,
      data: {
        id: paymentIntent.id,
        clientSecret: paymentIntent.client_secret!,
        status: paymentIntent.status,
        amount: paymentIntent.amount,
        currency: paymentIntent.currency
      },
      timestamp: Date.now()
    }
  } catch (error) {
    return {
      success: false,
      error: error instanceof Error ? error.message : 'Payment intent cancellation failed',
      timestamp: Date.now()
    }
  }
}

