/**
 * Create a Checkout Session
 *
 * Directly calls Stripe API using user's secret key.
 * No Zoer backend involved.
 *
 * @param options - Checkout session options with Stripe key
 * @returns Promise resolving to checkout session result
 *
 * @example One-time payment
 * ```typescript
 * const result = await stripe.createCheckoutSession({
 *   stripeKey: process.env.STRIPE_SECRET_KEY!,
 *   request: {
 *     mode: 'payment',
 *     lineItems: [{
 *       priceData: {
 *         currency: 'usd',
 *         unitAmount: 2000,
 *         productData: {
 *           name: 'T-Shirt',
 *           description: 'Comfortable cotton t-shirt'
 *         }
 *       },
 *       quantity: 1
 *     }],
 *     successUrl: 'https://example.com/success',
 *     cancelUrl: 'https://example.com/cancel'
 *   }
 * })
 *
 * // Redirect user to result.data.url
 * ```
 */
export async function createCheckoutSession(
  options: CreateCheckoutSessionOptions
): Promise<CheckoutSessionResult> {
  try {
    const stripe = new Stripe(options.stripeKey)

    const session = await stripe.checkout.sessions.create({
      mode: options.request.mode as 'payment' | 'subscription' | 'setup',
      line_items: options.request.lineItems.map(item => ({
        price_data: item.priceData ? {
          currency: item.priceData.currency,
          unit_amount: item.priceData.unitAmount,
          product_data: {
            name: item.priceData.productData.name,
            description: item.priceData.productData.description,
            images: item.priceData.productData.images
          },
          recurring: item.priceData.recurring ? {
            interval: item.priceData.recurring.interval as 'day' | 'week' | 'month' | 'year',
            interval_count: item.priceData.recurring.intervalCount
          } : undefined
        } : undefined,
        price: item.price,
        quantity: item.quantity
      })),
      success_url: options.request.successUrl,
      cancel_url: options.request.cancelUrl,
      customer: options.request.customerId,
      customer_email: options.request.customerEmail,
      metadata: options.request.metadata
    })

    return {
      success: true,
      data: {
        id: session.id,
        url: session.url!,
        status: session.status!
      },
      timestamp: Date.now()
    }
  } catch (error) {
    return {
      success: false,
      error: error instanceof Error ? error.message : 'Checkout session creation failed',
      timestamp: Date.now()
    }
  }
}

/**
 * Get Checkout Session details
 *
 * Retrieves details of a completed checkout session.
 * Useful for verifying payment status after redirect.
 *
 * @param stripeKey - User's Stripe key (secret or publishable)
 * @param request - Get session request with session ID
 * @returns Promise resolving to session details
 *
 * @example
 * ```typescript
 * // After user returns from Checkout
 * const result = await stripe.getCheckoutSession(
 *   process.env.STRIPE_SECRET_KEY!,
 *   { sessionId: 'cs_xxx' }
 * )
 *
 * if (result.success && result.data.paymentStatus === 'paid') {
 *   // Payment successful, fulfill order
 * }
 * ```
 */
export async function getCheckoutSession(
  stripeKey: string,
  request: GetCheckoutSessionRequest
): Promise<StripeResult<GetCheckoutSessionResponse>> {
  try {
    const stripe = new Stripe(stripeKey)

    const session = await stripe.checkout.sessions.retrieve(request.sessionId)

    return {
      success: true,
      data: {
        id: session.id,
        paymentStatus: session.payment_status!,
        customerId: session.customer as string,
        customerEmail: session.customer_email!,
        amountTotal: session.amount_total!,
        currency: session.currency!,
        metadata: session.metadata || undefined
      },
      timestamp: Date.now()
    }
  } catch (error) {
    return {
      success: false,
      error: error instanceof Error ? error.message : 'Failed to get checkout session',
      timestamp: Date.now()
    }
  }
}

