/**
 * Create a Stripe Customer
 *
 * Creates a customer record in Stripe.
 *
 * @param options - Customer options with Stripe secret key
 * @returns Promise resolving to customer result
 *
 * @example
 * ```typescript
 * const result = await stripe.createCustomer({
 *   stripeSecretKey: process.env.STRIPE_SECRET_KEY!,
 *   request: {
 *     email: 'customer@example.com',
 *     name: 'John Doe',
 *     metadata: {
 *       userId: '12345'
 *     }
 *   }
 * })
 *
 * if (result.success) {
 *   const customerId = result.data.id
 * }
 * ```
 */
export async function createCustomer(
  options: CreateCustomerOptions
): Promise<CustomerResult> {
  try {
    const stripe = new Stripe(options.stripeSecretKey)

    const customer = await stripe.customers.create({
      email: options.request.email,
      name: options.request.name,
      phone: options.request.phone,
      description: options.request.description,
      metadata: options.request.metadata
    })

    return {
      success: true,
      data: {
        id: customer.id,
        email: customer.email || undefined,
        name: customer.name || undefined,
        created: customer.created
      },
      timestamp: Date.now()
    }
  } catch (error) {
    return {
      success: false,
      error: error instanceof Error ? error.message : 'Customer creation failed',
      timestamp: Date.now()
    }
  }
}

/**
 * Update a Stripe Customer
 *
 * Updates customer information in Stripe.
 *
 * @param stripeSecretKey - User's Stripe secret key
 * @param request - Update customer request
 * @returns Promise resolving to customer result
 *
 * @example
 * ```typescript
 * const result = await stripe.updateCustomer(
 *   process.env.STRIPE_SECRET_KEY!,
 *   {
 *     customerId: 'cus_xxx',
 *     email: 'newemail@example.com',
 *     name: 'John Smith'
 *   }
 * )
 * ```
 */
export async function updateCustomer(
  stripeSecretKey: string,
  request: UpdateCustomerRequest
): Promise<CustomerResult> {
  try {
    const stripe = new Stripe(stripeSecretKey)

    const customer = await stripe.customers.update(
      request.customerId,
      {
        email: request.email,
        name: request.name,
        phone: request.phone,
        description: request.description,
        metadata: request.metadata
      }
    )

    return {
      success: true,
      data: {
        id: customer.id,
        email: customer.email || undefined,
        name: customer.name || undefined,
        created: customer.created
      },
      timestamp: Date.now()
    }
  } catch (error) {
    return {
      success: false,
      error: error instanceof Error ? error.message : 'Customer update failed',
      timestamp: Date.now()
    }
  }
}

