/**
 * AI Image Module
 * Text-to-image and image-to-image generation functionality
 */

import { getTextToImageEndpoint } from "../const";
import type {
  AIImageGenerationRequest,
  AIImageGenerationResponse,
  TextToImageOptions,
  TextToImageResult,
  ImageToImageOptions,
  ImageToImageResult
} from "./types";

// ============================================================================
// Internal API Communication
// ============================================================================

/**
 * Call AI image generation API on backend
 * This is a unified API that handles both text-to-image and image-to-image
 * @param request - AI image generation request parameters
 * @returns Promise resolving to AIImageGenerationResponse
 * @throws Error if request fails or returns invalid data
 */
async function callAIImageGenerationAPI(
  request: AIImageGenerationRequest
): Promise<AIImageGenerationResponse> {
  try {
    const response = await fetch(getTextToImageEndpoint(), {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify(request),
    });

    if (!response.ok) {
      throw new Error(
        `Failed to generate image: ${response.status} ${response.statusText}`
      );
    }

    const result = await response.json();

    // Backend returns DataResult<AIImageGenerationResponse>
    if (!result.success) {
      throw new Error(result.errorMessage || "Failed to generate image");
    }

    const data = result.data;

    // Validate required fields
    if (!data.imageUrl) {
      throw new Error("Invalid AI image generation response: missing imageUrl");
    }

    return {
      imageUrl: data.imageUrl,
    };
  } catch (error) {
    throw new Error(
      `Failed to call AI image generation API: ${
        error instanceof Error ? error.message : "Unknown error"
      }`
    );
  }
}

// ============================================================================
// Public Text-to-Image Function (Pure text prompt)
// ============================================================================

/**
 * Generate image from pure text prompt
 *
 * This function sends a text prompt to the backend,
 * which uses AI to generate an image based on the description.
 *
 * @param prompt - Text description of desired image (required)
 * @param options - Text-to-image options
 * @returns Promise resolving to generation result
 *
 * @example
 * ```typescript
 * const result = await textToImage(
 *   '一只可爱的卡通猫咪在草地上玩耍',
 *   { aspectRatio: '16:9' }
 * )
 *
 * if (result.success) {
 *   console.log('Generated image:', result.imageUrl)
 * } else {
 *   console.error('Generation failed:', result.error)
 * }
 * ```
 */
export async function textToImage(
  prompt: string,
  options: TextToImageOptions = {}
): Promise<TextToImageResult> {
  // Validate required parameters
  if (!prompt || prompt.trim() === "") {
    return {
      success: false,
      error: "Text prompt is required",
      timestamp: Date.now(),
    };
  }

  try {
    // Prepare request (no imageUrl for pure text-to-image)
    const request: AIImageGenerationRequest = {
      prompt: prompt.trim(),
      aspectRatio: options.aspectRatio || "1:1",
    };

    // Call backend API
    const response = await callAIImageGenerationAPI(request);

    return {
      success: true,
      imageUrl: response.imageUrl,
      timestamp: Date.now(),
    };
  } catch (error) {
    return {
      success: false,
      error: error instanceof Error ? error.message : "Text-to-image generation failed",
      timestamp: Date.now(),
    };
  }
}

// ============================================================================
// Public Image-to-Image Function (Reference image + text prompt)
// ============================================================================

/**
 * Generate image from reference image and text prompt
 *
 * This function sends a reference image URL and text prompt to the backend,
 * which uses AI to generate a new image based on the reference and description.
 *
 * @param imageUrl - URL of the reference image (required)
 * @param prompt - Text description of desired image transformation (required)
 * @param options - Image-to-image options
 * @returns Promise resolving to generation result
 *
 * @example
 * ```typescript
 * const result = await imageToImage(
 *   'https://example.com/photo.jpg',
 *   '把这张照片变成卡通风格',
 *   { aspectRatio: '1:1' }
 * )
 *
 * if (result.success) {
 *   console.log('Generated image:', result.imageUrl)
 * } else {
 *   console.error('Generation failed:', result.error)
 * }
 * ```
 */
export async function imageToImage(
  imageUrl: string,
  prompt: string,
  options: ImageToImageOptions = {}
): Promise<ImageToImageResult> {
  // Validate required parameters
  if (!imageUrl || imageUrl.trim() === "") {
    return {
      success: false,
      error: "Reference image URL is required",
      timestamp: Date.now(),
    };
  }

  if (!prompt || prompt.trim() === "") {
    return {
      success: false,
      error: "Text prompt is required",
      timestamp: Date.now(),
    };
  }

  try {
    // Prepare request
    const request: AIImageGenerationRequest = {
      imageUrl: imageUrl.trim(),
      prompt: prompt.trim(),
      aspectRatio: options.aspectRatio || "1:1",
    };

    // Call backend API
    const response = await callAIImageGenerationAPI(request);

    return {
      success: true,
      imageUrl: response.imageUrl,
      timestamp: Date.now(),
    };
  } catch (error) {
    return {
      success: false,
      error: error instanceof Error ? error.message : "Image-to-image generation failed",
      timestamp: Date.now(),
    };
  }
}
